package rs.unicredit.cardlifecycle.authentication;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.env.Environment;
import org.springframework.security.config.annotation.authentication.builders.AuthenticationManagerBuilder;
import org.springframework.security.config.annotation.authentication.configuration.GlobalAuthenticationConfigurerAdapter;

@Configuration
public class AuthenticationConfiguration extends GlobalAuthenticationConfigurerAdapter {
	
	private final Logger logger = LoggerFactory.getLogger(this.getClass());

	@Autowired
	Environment env;
	
	@Autowired
	RestAuthenticationProvider restAuth;

	@Autowired
	LdapAuthenticationProvider ldapAuth;
	
	@Override
    public void init(AuthenticationManagerBuilder auth) throws Exception {
		String mode = env.getProperty("customs.auth-mode");
		if (mode == null || mode.trim().isEmpty()) {
			mode = "KEYCLOAK";
		} else {
			mode = mode.trim();
		}
		switch (mode) {
			case "LDAP":
				if (ldapAuth != null) {
					ldapAuth.configure(auth);
					logger.info("LDAP Authentication provider is configured.");
				} else {
					logger.warn("LDAP Authentication provider requested but not available.");
				}
				break;
			case "REST":
				if (restAuth != null) {
					auth.authenticationProvider(restAuth);
					logger.info("REST Authentication provider is configured.");
				} else {
					logger.warn("REST Authentication provider requested but not available.");
				}
				break;
			case "KEYCLOAK":
			default:
				logger.info("KEYCLOAK Authorization provider is configured.");
		}
    	
    }

}

