package rs.unicredit.cardlifecycle.security;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.env.Environment;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.oauth2.jwt.JwtDecoder;
import org.springframework.security.oauth2.jwt.NimbusJwtDecoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

import rs.unicredit.cardlifecycle.security.jwt.AuthEntryPointJwt;
import rs.unicredit.cardlifecycle.security.jwt.AuthTokenFilter;
import rs.unicredit.cardlifecycle.security.jwt.KeycloakService;
import rs.unicredit.cardlifecycle.security.services.UserDetailsServiceImpl;

import java.security.KeyFactory;
import java.security.interfaces.RSAPublicKey;
import java.security.spec.X509EncodedKeySpec;
import java.util.Base64;

@Configuration
@EnableMethodSecurity
public class WebSecurityConfig {

    @Autowired
    private Environment env;

    @Autowired
    private AuthEntryPointJwt unauthorizedHandler;

    @Autowired
    private KeycloakService keycloakService;

    @Autowired
    private UserDetailsServiceImpl userDetailsService;

    private static final String[] PUBLIC_URLS = {
        "/api/auth/**", "/api/test/**", "/api/files/**", "/api-docs/**",
        "/swagger-ui/**", "/swagger-resources/**", "/swagger-ui.html", 
        "/proxy/**", "/v3/api-docs/**" };

    @Bean
    public AuthTokenFilter authenticationJwtTokenFilter() {
        return new AuthTokenFilter();
    }

    @Bean
    public DaoAuthenticationProvider authenticationProvider() {
        DaoAuthenticationProvider authProvider = new DaoAuthenticationProvider();
        authProvider.setUserDetailsService(userDetailsService);
        authProvider.setPasswordEncoder(passwordEncoder());
        return authProvider;
    }

    @Bean
    public AuthenticationManager authenticationManager(AuthenticationConfiguration authConfig) throws Exception {
        return authConfig.getAuthenticationManager();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        // Use a strong one-way hash for credential storage/verification
        return new BCryptPasswordEncoder();
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        String authMode = env.getProperty("customs.auth-mode", "LOCAL").toUpperCase();

        if ("KEYCLOAK".equals(authMode)) {
            configureKeycloakSecurity(http);
        } else {
            configureLocalSecurity(http);
        }

        return http.build();
    }

    private void configureKeycloakSecurity(HttpSecurity http) throws Exception {
        applyCommonSecuritySettings(http)
            .oauth2ResourceServer(oauth2 -> oauth2.jwt(jwt -> jwt.decoder(keycloakService.getJwtDecoder())));
    }

    private void configureLocalSecurity(HttpSecurity http) throws Exception {
        applyCommonSecuritySettings(http)
            .exceptionHandling(exception -> exception.authenticationEntryPoint(unauthorizedHandler))
            .authenticationProvider(authenticationProvider())
            .addFilterBefore(authenticationJwtTokenFilter(), UsernamePasswordAuthenticationFilter.class);
    }

    private HttpSecurity applyCommonSecuritySettings(HttpSecurity http) throws Exception {
        return http.csrf(csrf -> csrf.disable())
                   .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                   .authorizeHttpRequests(auth -> auth
                       .requestMatchers(PUBLIC_URLS).permitAll()
                       .anyRequest().authenticated());
    }

    @Bean
    public FilterRegistrationBean<RateLimitFilter> rateLimitFilterRegistration(RateLimitFilter filter) {
        FilterRegistrationBean<RateLimitFilter> registration = new FilterRegistrationBean<>();
        registration.setFilter(filter);
        registration.addUrlPatterns("/api/*"); // primeni na API rute
        registration.setOrder(0); // izvr­ava se pre ostalih filtera
        return registration;
    }
}

