	@Value("${customs.jasper.cibCardPropratnoUrl}")
	private String cibCardPropratnoUrl;

	@Autowired
	CardDestinationService cds;

	@Override
	public List<FileMetadata> getAllUnimportedFiles() throws IOException, FileImportException {
		logger.info("***Read all unimported files from: {}***", pathFrom);
		List<FileMetadata> listMetaData = new ArrayList<>();
		File dir = new File(pathFrom);
		if (dir.isDirectory()) {
			File[] listDir = dir.listFiles();
			if (listDir != null) {
				for (File file : listDir) {
					if (file.isFile()) {
						Path f = Paths.get(pathFrom + File.separator + file.getName());
						BasicFileAttributes attr = Files.readAttributes(f, BasicFileAttributes.class);
						FileTime date = attr.creationTime();
						String formattedCreationTime = localFormatDate(date);

						int lineCount;
						try {
							lineCount = countlLinesInFiles(f);
						} catch (Exception e) {
							logger.info("Error counting lines in file: {}", file.getName());
							throw new FileImportException("Erros counting lines in files" + file.getName());
						}
						listMetaData.add(new FileMetadata(file, formattedCreationTime, pathFrom + File.separator + file.getName(), file.getName(), 0, lineCount));
					}
				}
			}
		}

		logger.info("***Number of files: {}***", listMetaData.size());
		listMetaData.sort(Comparator.comparingInt(FileMetadata::getLineCount));
		logger.info("*** Zavrseno sortiranje liste ASC ***");
		return listMetaData;
	}

	private static String localFormatDate(FileTime fileTime) {
		LocalDateTime localDateTime = LocalDateTime.ofInstant(fileTime.toInstant(), java.time.ZoneId.systemDefault());
		DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd-MMM-yyyy");
		return localDateTime.format(formatter);
	}

	@Override
	public String createArchiveStructureIfNotExist() {

		Date datum = new Date();
		SimpleDateFormat sdfGodina = new SimpleDateFormat("yyyy");
		SimpleDateFormat sdfMesec = new SimpleDateFormat("MMMM");
		SimpleDateFormat sdfMesecNo = new SimpleDateFormat("M");
		SimpleDateFormat sdfDan = new SimpleDateFormat("dd");

		String godina = sdfGodina.format(datum);
		String mesec = sdfMesec.format(datum);
		String mesecNo = sdfMesecNo.format(datum);
		
		String dan = sdfDan.format(datum);

		String putanjaDoGodine = archivedPath + "/" + godina;
		String putanjaDoMeseca = putanjaDoGodine + "/" + mesecNo + ". " + mesec;
		String putanjaDoDana = putanjaDoMeseca + "/" + dan;

		createDirectory(putanjaDoGodine);
		createDirectory(putanjaDoMeseca);
		createDirectory(putanjaDoDana);

		return putanjaDoDana;

	}

	@Override
	public String createExportedArchiveStructureIfNotExist() {

		Date datum = new Date();
		SimpleDateFormat sdfGodina = new SimpleDateFormat("yyyy");
		SimpleDateFormat sdfMesec = new SimpleDateFormat("MMMM");
		SimpleDateFormat sdfDan = new SimpleDateFormat("dd");

		String godina = sdfGodina.format(datum);
		String mesec = sdfMesec.format(datum);
		String dan = sdfDan.format(datum);

		String putanjaDoGodine = outArchivedPath + "/" + godina;
		String putanjaDoMeseca = putanjaDoGodine + "/" + mesec;
		String putanjaDoDana = putanjaDoMeseca + "/" + dan;

		createDirectory(putanjaDoGodine);
		createDirectory(putanjaDoMeseca);
		createDirectory(putanjaDoDana);

		return putanjaDoDana;

	}

	public void createDirectory(String path) {
		File dir = new File(path);
		if (!dir.exists()) {
			dir.mkdir();

		}

