		Path odredisnaMapa = Paths.get(cutTo);
		Path odredisnaDatoteka = odredisnaMapa.resolve(fileName);
		if (!izvornaDatoteka.exists() || !izvornaDatoteka.isFile()) {
			logger.error("File not found or is not a regular file: {}", fileName);
			return;
		}
		try {
