			if (!Files.exists(odredisnaMapa)) {
				Files.createDirectories(odredisnaMapa);
			}
			Files.move(izvornaDatoteka.toPath(), odredisnaDatoteka, StandardCopyOption.REPLACE_EXISTING);
			logger.info("Moved file from {} to: {}", izvornaDatoteka.toPath(), odredisnaDatoteka);
			if (Files.exists(izvornaDatoteka.toPath())) {
				Files.delete(izvornaDatoteka.toPath());
			} else {
				logger.warn("Original file was already moved, skipping delete.");
			}
