	public void copyFileToDestination(String fullPathToFile, String pathTo) {
		logger.info("usao u copyFileToDestination!!!!!!!");
		File sourceFile = new File(fullPathToFile);
		Path destinationDirectory = Paths.get(pathTo);
		Path destinationFile = destinationDirectory.resolve(sourceFile.getName());

		// Debug log - provera putanja
		logger.info("Source file path: {}", sourceFile.getAbsolutePath());
		logger.info("Destination file path: {}", destinationFile);

		// Provera da li izvorni fajl postoji
		if (!sourceFile.exists() || !sourceFile.isFile()) {
			logger.error("File not found or is not a regular file: {}", fullPathToFile);
			return;
		}

		try {
			// Provera da li ciljni direktorijum postoji
			if (!Files.exists(destinationDirectory)) {
				logger.info("Target directory does not exist, creating: {}", destinationDirectory);
				Files.createDirectories(destinationDirectory);
			}

			// Dodatna provera odmah nakon kreiranja direktorijuma
			if (!Files.exists(destinationDirectory)) {
				logger.error("Failed to create directory: {}", destinationDirectory);
				return;
			}

			// Provera dozvola za pisanje u ciljni direktorijum
			if (!Files.isWritable(destinationDirectory)) {
				logger.error("No write permission for directory: {}", destinationDirectory);
				return;
			}

			// Provera dozvola za pisanje sa `File` klasom
			File targetDir = new File(pathTo);
			if (!targetDir.canWrite()) {
				logger.error("Cannot write to directory using File.canWrite(): {}", pathTo);
				return;
			}

			// Kopiranje fajla
			logger.info("krece kopiranje fajla u copyFileToDestination!!!!!!!");
			logger.info("krece kopiranje fajla sourceFile.toPath(): {} ",sourceFile.toPath());
			logger.info("krece kopiranje fajla(destinationFile {} ",destinationFile);
			Files.copy(sourceFile.toPath(), destinationFile, StandardCopyOption.REPLACE_EXISTING);
			logger.info("Copied file: {} to: {}", fullPathToFile, pathTo);
		} catch (IOException e) {
			logger.error("Error while copying file error: {}", fullPathToFile, e);
		}
	}
	public void copyAllFilesToDestination(String sourceFolderPath, String baseDestinationFolderPath) {
		logger.info("Pokretanje kopiranja svih fajlova iz: {} -> {}", sourceFolderPath, baseDestinationFolderPath);

		File sourceFolder = new File(sourceFolderPath);
		LocalDate today = LocalDate.now();
		String year = String.valueOf(today.getYear());
		String month = today.format(DateTimeFormatter.ofPattern("MM"));
		String day = today.format(DateTimeFormatter.ofPattern("dd"));

		// Kreiranje putanje sa strukturom: godina / mesec / dan
		Path structuredDestinationFolder = Paths.get(baseDestinationFolderPath, year, month, day);

		try {
			// Kreiranje foldera ako ne postoji
			Files.createDirectories(structuredDestinationFolder);
			logger.info("Created directory structure: {}", structuredDestinationFolder);
		} catch (IOException e) {
			logger.error("Failed to create directory structure: {}", structuredDestinationFolder, e);
			return;
		}

		// Iteracija kroz fajlove i kopiranje
		File[] files = sourceFolder.listFiles();
		if (files != null) {
			for (File file : files) {
				if (file.isFile()) { // Kopira samo fajlove, ne poddirektorijume
					Path destinationFile = structuredDestinationFolder.resolve(file.getName());
					try {
						Files.copy(file.toPath(), destinationFile, StandardCopyOption.REPLACE_EXISTING);
						logger.info("Copied file: {} to {}", file.getAbsolutePath(), destinationFile);
					} catch (IOException e) {
						logger.error("Error while copying file: {}", file.getAbsolutePath(), e);
					}
				}
			}
		} else {
			logger.warn("No files found in source directory: {}", sourceFolderPath);
		}
	}
