	@Override
	public void stampaOtpremnice() throws IOException {
		logger.info("***********************BEGIN stampaOtpremnice ***********************");
		String URLJasper = otpremniceUrl;
		URL url = new URL(URLJasper);
		HttpURLConnection connection = (HttpURLConnection) url.openConnection();
		connection.setRequestMethod("GET");

		int responseCode = connection.getResponseCode();
		if (responseCode == HttpURLConnection.HTTP_OK) {
			InputStream inputStream = connection.getInputStream();
			LocalDateTime currentDateTime = LocalDateTime.now();
			DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy.MM.dd.HHmmss");
			String formattedDateTime = currentDateTime.format(formatter);
			String outputFile = otpremnicePath + File.separator + "PersoOtpremnica" + formattedDateTime + ".pdf";
			OutputStream outputStream = new FileOutputStream(outputFile);
			byte[] buffer = new byte[4096];
			int bytesRead;
			while ((bytesRead = inputStream.read(buffer)) != -1) {
				outputStream.write(buffer, 0, bytesRead);
			}
			outputStream.close();
			inputStream.close();
			logger.info("PDF PersoOtpremnica downloaded and saved to " + outputFile);
		} else {
			logger.error("HTTP request failed with response code: {}", responseCode);
		}
		connection.disconnect();
		// URL sa servera end
	}

