	private static ArchiveDirectory listAllFiles(Path currentPath) throws IOException {
		ArchiveDirectory archiveDirectory = new ArchiveDirectory();
		archiveDirectory.setTitle(currentPath.getFileName().toString());
		archiveDirectory.setDirectory(Files.isDirectory(currentPath));
		if (archiveDirectory.isDirectory()) {
			List<ArchiveDirectory> childrens = new ArrayList<>();
			try (DirectoryStream<Path> stream = Files.newDirectoryStream(currentPath)) {
				for (Path entry : stream) {
					childrens.add(listAllFiles(entry));
				}
			}
			archiveDirectory.setChildren(childrens);
		}
		return archiveDirectory;
	}

	@Override
	public List<FileMetadata> getAllExportedFiles() throws IOException, FileImportException {
		logger.info("***Read all exported files from: {}***", pathTo);
		List<FileMetadata> listMetaData = new ArrayList<>();
		File dir = new File(pathTo);
		if (dir.isDirectory()) {
			File[] listDir = dir.listFiles();
			if (listDir != null) {
				for (File file : listDir) {
					if (file.isFile()) {
						Path f = Paths.get(pathTo + File.separator + file.getName());
						BasicFileAttributes attr = Files.readAttributes(f, BasicFileAttributes.class);
						FileTime date = attr.creationTime();
						String formattedCreationTime = localFormatDate(date);

						int lineCount;
						try {
							lineCount = countlLinesInFiles(f);
						} catch (Exception e) {
							logger.info("Error counting lines in file: {}", file.getName());
							throw new FileImportException("Erros counting lines in files" + file.getName());
						}
						listMetaData.add(new FileMetadata(file, formattedCreationTime, pathTo + "\\" + file.getName(), file.getName(), 0, lineCount));
					}
				}
			}

		}
		return listMetaData;

	}

	private Integer countlLinesInFiles (Path filePath) throws IOException {
		CharsetDecoder decoder = StandardCharsets.UTF_8.newDecoder()
				.onMalformedInput(CodingErrorAction.IGNORE)
				.onUnmappableCharacter(CodingErrorAction.IGNORE);

		try (BufferedReader reader = new BufferedReader(new InputStreamReader(Files.newInputStream(filePath), decoder))) {
			int lineCount = 0;
			String line;
			while ((line = reader.readLine()) != null) {
				lineCount++;
			}
			return  lineCount;
		} catch (IOException e) {
			e.printStackTrace();
		}
		return  0;
	}

}

