import rs.unicredit.cardlifecycle.model.Perso;
import rs.unicredit.cardlifecycle.model.PersoHistory;
import rs.unicredit.cardlifecycle.repository.CardRegistrationHistoryRepository;
import rs.unicredit.cardlifecycle.repository.PersoHistoryRepository;

import java.time.LocalDateTime;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.verify;

@ExtendWith(MockitoExtension.class)
class PersoHistoryServiceImplTest {

    @Mock
    private PersoHistoryRepository persoHistoryRepo;

    @Mock
    private CardRegistrationHistoryRepository crhr;

    @InjectMocks
    private PersoHistoryServiceImpl service;

    @Test
    void saveLog_persistsHistoryEntry() {
        Perso p = new Perso();
        p.setFileExportName("exp");
        p.setFileExportTime(LocalDateTime.now());
        p.setFileImportName("imp");
        p.setFileImportTime(LocalDateTime.now());
        p.setStatus("status");
        p.setOPaket("paket");
        p.setOStatus("oStatus");
        p.setOBranch("branch");
        p.setOPxcode("px");

        LocalDateTime now = LocalDateTime.now();

        service.saveLog(p, now, now, "user1", "action1");

        ArgumentCaptor<PersoHistory> captor = ArgumentCaptor.forClass(PersoHistory.class);
        verify(persoHistoryRepo).save(captor.capture());
        PersoHistory saved = captor.getValue();
        assertEquals("exp", saved.getFileExportName());
        assertEquals("imp", saved.getFileImportName());
        assertEquals("status", saved.getStatus());
        assertEquals("user1", saved.getUpdatedBy());
        assertEquals("px", saved.getOPxcode());
        assertEquals("action1", saved.getAction());
    }
}

